from datetime import datetime

def parse(line):
    date, time, status, ip, user = line.split()
    ts = datetime.strptime(date + " " + time, "%Y-%m-%d %H:%M:%S")
    return {"ts": ts, "ok": status == "OK", "ip": ip, "user": user}

def burst_ips(rows, limit, window):
    times = {}
    for r in rows:
        if not r["ok"]:
            times.setdefault(r["ip"], []).append(r["ts"])
    bad = []
    for ip, ts in times.items():
        ts.sort()
        for i in range(len(ts) - limit + 1):
            if (ts[i + limit - 1] - ts[i]).total_seconds() <= window:
                bad.append(ip)
                break
    return sorted(bad)

with open("auth.log", encoding="utf-8") as f:
    rows = [parse(l) for l in f if l.strip()]
print(burst_ips(rows, 3, 60))

