limit = int(input())
window = int(input())
with open("auth.log", encoding="utf-8") as f:
    rows = [parse(l) for l in f if l.strip()]
bad = burst_ips(rows, limit, window)
if bad:
    for ip in bad:
        n = sum(1 for r in rows if r["ip"] == ip and not r["ok"])
        print("ALERT " + ip + " failures=" + str(n))
else:
    print("all clear")
